CREATE OR REPLACE VIEW ldl_p_lew_mart_wfm.v_season_warehouse_subitemgrp_2 (iso_cd, dat_calendar, wh_id, subitemgroup_id,
currency_iso_cd, write_off_gross, write_off_net, price_change_gross, price_change_net, turnover_gross, turnover_net,
update_timestamp) AS
/* for not matching values of subitemgroup_id, -666 is used since on full join both side does not match */
/* for not matching values of subitemgroup_id, -666 is used since on full join both side does not match */ SELECT
 COALESCE(wo_pc.iso_cd, to_sub.iso_cd) AS iso_cd,
 COALESCE(wo_pc.dat_calendar, to_sub.dat_calendar) AS dat_calendar,
 COALESCE(wo_pc.wh_id, to_sub.wh_id) AS wh_id,
 COALESCE(wo_pc.subitemgroup_id, to_sub.subitemgroup_id) AS subitemgroup_id,
 COALESCE(wo_pc.currency_iso_cd, to_sub.currency_iso_cd) AS currency_iso_cd,
 wo_pc.abschriftenwerttotalbrutto AS write_off_gross,
 wo_pc.abschriftenwerttotalnetto AS write_off_net,
 wo_pc.pvwerttotalbrutto AS price_change_gross,
 wo_pc.pvwerttotalnetto AS price_change_net,
 to_sub.umsatzbrutto AS turnover_gross,
 to_sub.umsatznetto AS turnover_net,
 PARSE_DATETIME('%Y%m%d%I24%M%S9S6', GREATEST(COALESCE(FORMAT_DATETIME('%Y%m%d%I24%M%S9S6', wo_pc.update_timestamp),
    '19000101000000000000'), COALESCE(FORMAT_DATETIME('%Y%m%d%I24%M%S9S6', to_sub.update_timestamp),
    '19000101000000000000'))) AS update_timestamp
FROM (SELECT IFNULL(item.subitemgroup_id, - 666) AS subitemgroup_id,
   agg_wh_item_sfo.booking_dat AS dat_calendar,
   agg_wh_item_sfo.wh_id,
   agg_wh_item_sfo.client_id,
   CLI.country_cd AS iso_cd,
   agg_wh_item_sfo.currency_iso_cd,
   MAX(run_log_loc.update_timestamp) AS update_timestamp,
   SUM(CASE
     WHEN agg_wh_item_sfo.sfotype_id IN (137, 147, 181, 182, 191, 192)
     THEN IFNULL(agg_wh_item_sfo.sfo_wrtoff_zero_rtl_rl_val_asis, 0) + IFNULL(agg_wh_item_sfo.sfo_total_rtl_rl_val_asis
       , 0)
     ELSE NULL
     END) AS abschriftenwerttotalbrutto,
   SUM(CASE
     WHEN agg_wh_item_sfo.sfotype_id IN (137, 147, 181, 182, 191, 192)
     THEN IFNULL(agg_wh_item_sfo.sfo_wrtoff_zero_rtl_rl_net_val_asis, 0) + IFNULL(agg_wh_item_sfo.sfo_total_rtl_rl_net_val_asis
       , 0)
     ELSE NULL
     END) AS abschriftenwerttotalnetto,
   SUM(CASE
     WHEN agg_wh_item_sfo.sfotype_id IN (144, 134, 180, 190)
     THEN agg_wh_item_sfo.sfo_total_rtl_rl_val_asis
     ELSE NULL
     END) AS pvwerttotalbrutto,
   SUM(CASE
     WHEN agg_wh_item_sfo.sfotype_id IN (144, 134, 180, 190)
     THEN agg_wh_item_sfo.sfo_total_rtl_rl_net_val_asis
     ELSE NULL
     END) AS pvwerttotalnetto
  FROM (SELECT AGG_WH_SFO.client_id,
     AGG_WH_SFO.loc_sid_wh,
     WH.src_wh_id AS wh_id,
     ITMP.item_sid_map AS item_id,
     AGG_WH_SFO.booking_dat,
     AGG_WH_SFO.curr_cd_from AS currency_iso_cd,
     AGG_WH_SFO.sfotype_id,
     AGG_WH_SFO.sfo_wrtoff_zero_rtl_rl_val_asis,
     AGG_WH_SFO.sfo_total_rtl_rl_val_asis,
     AGG_WH_SFO.sfo_wrtoff_zero_rtl_rl_net_val_asis,
     AGG_WH_SFO.sfo_total_rtl_rl_net_val_asis
    FROM ldl_p_lew_bil_ac.v_agg_wh_day_item_sfo_asis_2 AS AGG_WH_SFO
     INNER JOIN ldl_p_lew_bil_ac.v_warehouse_2 AS WH ON AGG_WH_SFO.client_id = WH.client_id AND AGG_WH_SFO.loc_sid_wh = WH
        .loc_sid_wh AND WH.dwh_actual_fg = 1
     INNER JOIN ldl_p_lew_core_ac.v_item_map_key_2 AS ITMP ON AGG_WH_SFO.client_id = ITMP.client_id AND AGG_WH_SFO.item_sid
        = ITMP.item_sid) AS agg_wh_item_sfo
   LEFT JOIN (SELECT VI.client_id,
     CAST(VI.item_sid AS BIGNUMERIC) AS item_id,
      CASE
      WHEN VI.src_matnr IS NULL
      THEN WAWI.subitemgroup_id
      ELSE ROUND(CAST(VIG.src_matkl AS BIGNUMERIC), 0)
      END AS subitemgroup_id
    FROM ldl_p_lew_core_ac.v_item_2 AS VI
     INNER JOIN ldl_p_lew_core_ac.v_item_hist_2 AS VIH ON VI.client_id = VIH.client_id AND VI.item_sid = VIH.item_sid AND
       CURRENT_DATE BETWEEN VIH.dwh_valid_from AND VIH.dwh_valid_to
     LEFT JOIN ldl_p_lew_core_ac.v_item_group_2 AS VIG ON VIH.client_id = VIG.client_id AND VIH.item_grp_sid = VIG.item_grp_sid
       
     LEFT JOIN ldl_p_lew_core_ac.v_wawi_itm_item_act_2 AS WAWI ON VI.client_id = WAWI.client_id AND VI.item_sid = WAWI.item_sid
       ) AS item_2 ON agg_wh_item_sfo.client_id = item.client_id AND agg_wh_item_sfo.item_id = item.item_id
   INNER JOIN ldl_p_lew_core_ac.v_wawi_ref_currency_act_2 AS CURR ON agg_wh_item_sfo.client_id = CURR.client_id AND
     agg_wh_item_sfo.currency_iso_cd = CURR.currency_iso_cd
   INNER JOIN ldl_p_lew_core_ac.v_client_2 AS CLI ON CURR.client_id = CLI.client_id AND CURR.currency_iso_cd = CLI.curr_cd
     
   INNER JOIN (SELECT client_id,
     dwh_cal_dt,
     MAX(update_timestamp) AS update_timestamp
    FROM ldl_p_lew_process_ac.v_agc_run_log_location_2
    WHERE aggregate_name = 't_agg_store_day_item_sfo_2'
    GROUP BY client_id,
     dwh_cal_dt) AS run_log_loc ON agg_wh_item_sfo.client_id = run_log_loc.client_id AND agg_wh_item_sfo.booking_dat =
     run_log_loc.dwh_cal_dt
  GROUP BY subitemgroup_id,
   dat_calendar,
   agg_wh_item_sfo.wh_id,
   agg_wh_item_sfo.client_id,
   iso_cd,
   agg_wh_item_sfo.currency_iso_cd) AS wo_pc
 FULL JOIN (SELECT IFNULL(item_q.subitemgroup_id, - 666) AS subitemgroup_id,
   agg_pos_wh_item.dwh_cal_dt AS dat_calendar,
   agg_pos_wh_item.wh_id,
   agg_pos_wh_item.client_id,
   CLIE.country_cd AS iso_cd,
   agg_pos_wh_item.currency_iso_cd,
   MAX(run_log.update_timestamp) AS update_timestamp,
   SUM(IFNULL(agg_pos_wh_item.sales_gross_val / agg_pos_wh_item.rate_currency_exchange, 0) + IFNULL(agg_pos_wh_item.return_gross_val
        / agg_pos_wh_item.rate_currency_exchange, 0)) AS umsatzbrutto,
   SUM(IFNULL(agg_pos_wh_item.sales_net_val / agg_pos_wh_item.rate_currency_exchange, 0) + IFNULL(agg_pos_wh_item.return_net_val
        / agg_pos_wh_item.rate_currency_exchange, 0)) AS umsatznetto
  FROM (SELECT AGG_POS_WH.dwh_cal_dt,
     AGG_POS_WH.client_id,
     AGG_POS_WH.sales_gross_val,
     AGG_POS_WH.sales_net_val,
     AGG_POS_WH.return_gross_val,
     AGG_POS_WH.return_net_val,
     ITMP0.item_sid_map AS item_id,
     CRY.currency_iso_cd,
     CRY.rate_currency_exchange,
     WH0.src_wh_id AS wh_id
    FROM ldl_p_lew_bil_ac.v_agg_pos_wh_day_item_asis_2 AS AGG_POS_WH
     INNER JOIN ldl_p_lew_bil_ac.v_warehouse_2 AS WH0 ON AGG_POS_WH.client_id = WH0.client_id AND AGG_POS_WH.loc_sid_wh =
        WH0.loc_sid_wh AND WH0.dwh_actual_fg = 1
     INNER JOIN ldl_p_lew_core_ac.v_wawi_ref_client_currency_rate_2 AS CRY ON AGG_POS_WH.client_id = CRY.client_id AND
       CURRENT_DATE BETWEEN CRY.dat_rec_start AND CRY.dat_rec_end
     INNER JOIN ldl_p_lew_core_ac.v_item_map_key_2 AS ITMP0 ON AGG_POS_WH.client_id = ITMP0.client_id AND AGG_POS_WH.item_sid
        = ITMP0.item_sid) AS agg_pos_wh_item
   LEFT JOIN (SELECT VI0.client_id,
     CAST(VI0.item_sid AS BIGNUMERIC) AS item_id,
      CASE
      WHEN VI0.src_matnr IS NULL
      THEN WAWI0.subitemgroup_id
      ELSE ROUND(CAST(VIG0.src_matkl AS BIGNUMERIC), 0)
      END AS subitemgroup_id
    FROM ldl_p_lew_core_ac.v_item_2 AS VI0
     INNER JOIN ldl_p_lew_core_ac.v_item_hist_2 AS VIH0 ON VI0.client_id = VIH0.client_id AND VI0.item_sid = VIH0.item_sid
         AND CURRENT_DATE BETWEEN VIH0.dwh_valid_from AND VIH0.dwh_valid_to
     LEFT JOIN ldl_p_lew_core_ac.v_item_group_2 AS VIG0 ON VIH0.client_id = VIG0.client_id AND VIH0.item_grp_sid = VIG0.item_grp_sid
       
     LEFT JOIN ldl_p_lew_core_ac.v_wawi_itm_item_act_2 AS WAWI0 ON VI0.client_id = WAWI0.client_id AND VI0.item_sid =
       WAWI0.item_sid) AS item_q ON agg_pos_wh_item.client_id = item_q.client_id AND agg_pos_wh_item.item_id = item_q.item_id
     
   INNER JOIN ldl_p_lew_core_ac.v_wawi_ref_currency_act_2 AS REF_CURR ON agg_pos_wh_item.client_id = REF_CURR.client_id
    AND agg_pos_wh_item.currency_iso_cd = REF_CURR.currency_iso_cd
   INNER JOIN ldl_p_lew_core_ac.v_client_2 AS CLIE ON REF_CURR.client_id = CLIE.client_id AND REF_CURR.currency_iso_cd =
     CLIE.curr_cd
   INNER JOIN (SELECT client_id,
     dwh_cal_dt,
     MAX(update_timestamp) AS update_timestamp
    FROM ldl_p_lew_process_ac.v_agc_run_log_2
    WHERE aggregate_name = 't_agg_pos_wh_day_item_asis_2'
    GROUP BY client_id,
     dwh_cal_dt) AS run_log ON agg_pos_wh_item.client_id = run_log.client_id AND agg_pos_wh_item.dwh_cal_dt = run_log.dwh_cal_dt
     
  GROUP BY subitemgroup_id,
   dat_calendar,
   agg_pos_wh_item.wh_id,
   agg_pos_wh_item.client_id,
   iso_cd,
   agg_pos_wh_item.currency_iso_cd) AS to_sub ON wo_pc.client_id = to_sub.client_id AND wo_pc.dat_calendar = to_sub.dat_calendar
        AND wo_pc.subitemgroup_id = to_sub.subitemgroup_id AND wo_pc.wh_id = to_sub.wh_id AND wo_pc.iso_cd = to_sub.iso_cd
     AND wo_pc.currency_iso_cd = to_sub.currency_iso_cd;